CREATE TABLE IF NOT EXISTS cbt_tests ( id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, target_type TEXT, target_id TEXT NOT NULL, modules TEXT, time_limit_minutes INTEGER NOT NULL DEFAULT 30, passing_score INTEGER DEFAULT 60, status TEXT DEFAULT 'pending_approval', created_by TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP ); CREATE TABLE IF NOT EXISTS cbt_questions ( id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES cbt_tests(id) ON DELETE CASCADE, question_type TEXT NOT NULL, question_text TEXT NOT NULL, options TEXT, correct_answer TEXT, max_points INTEGER DEFAULT 10, created_at DATETIME DEFAULT CURRENT_TIMESTAMP ); CREATE TABLE IF NOT EXISTS cbt_submissions ( id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES cbt_tests(id) ON DELETE CASCADE, intern_id TEXT NOT NULL, answers TEXT, proctoring_logs TEXT, score INTEGER, max_score INTEGER, passed INTEGER, ai_feedback TEXT, status TEXT DEFAULT 'submitted', submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP, created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
